contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint amount, uint funding) public payable {
        require(funding > 0);
        require(amount > 0);
        // fund c so it has spendable balance (owner transfer into c)
        c.sendTo(address(this), 0);
        address(c).call{value: funding}("");
        require(address(this).balance >= funding);
        uint beforeC = address(c).balance;
        bool reverted;
        if (amount > beforeC) {
            try c.sendTo(receiver, amount) { reverted = false; } catch { reverted = true; }
            assert(reverted && address(c).balance == beforeC);
        } else {
            try c.sendTo(receiver, amount) { reverted = false; } catch { reverted = true; }
            assert(!reverted && address(c).balance == beforeC - amount);
        }
    }
    receive() external payable {}
}

